import java.util.ArrayList;
import java.util.Arrays;

public class EvenFilterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ArrayList<Integer> mixed = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5, 6));
        check("mixed list", "[2, 4, 6]", EvenFilter.filterEvens(mixed).toString());
        check("original list is unchanged", "[1, 2, 3, 4, 5, 6]", mixed.toString());

        ArrayList<Integer> odds = new ArrayList<>(Arrays.asList(1, 3, 5));
        check("all odd numbers", "[]", EvenFilter.filterEvens(odds).toString());

        ArrayList<Integer> empty = new ArrayList<>();
        check("empty list", "[]", EvenFilter.filterEvens(empty).toString());

        ArrayList<Integer> tricky = new ArrayList<>(Arrays.asList(0, -2, -3, 7, 8));
        check("zero and negatives", "[0, -2, 8]", EvenFilter.filterEvens(tricky).toString());

        ArrayList<Integer> allEven = new ArrayList<>(Arrays.asList(2, 4));
        check("returns a new list, not the original", false, EvenFilter.filterEvens(allEven) == allEven);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

