import java.util.ArrayList;

public class EvenFilter {

    public static ArrayList<Integer> filterEvens(ArrayList<Integer> numbers) {
        ArrayList<Integer> evens = new ArrayList<>();
        for (int value : numbers) {
            if (value % 2 == 0) {
                evens.add(value);
            }
        }
        return evens;
    }
}
